Write {"file_path":"D:\code\ESI.ts\tests\bdd\step-definitions\core\contacts.steps.ts","content":"import { defineFeature, loadFeature } from 'jest-cucumber';
import { EsiClient } from '../../../../src/EsiClient';
import { EsiError } from '../../../../src/core/util/error';
import { TestDataFactory } from '../../../../src/testing/TestDataFactory';

const feature = loadFeature('tests/bdd/features/core/contacts.feature');

defineFeature(feature, (test) => {
  let client: EsiClient;

  beforeEach(() => {
    client = new EsiClient({
      clientId: 'test-client',
      baseUrl: 'https://esi.evetech.net',
      timeout: 5000,
    });
  });

  test('WHEN getCharacterContacts is called the client shall return contacts with standings', ({ given, when, then }) => {
    const characterId = 1689391488;
    let result: any;

    given('a valid character ID and an authenticated ESI client with contacts data', () => {
      const expectedContacts = [
        {
          contact_id: 123456789,
          contact_type: 'character' as const,
          standing: 10.0,
          label_ids: [1],
        },
        {
          contact_id: 987654321,
          contact_type: 'corporation' as const,
          standing: 5.0,
          label_ids: [2],
        },
        {
          contact_id: 99005338,
          contact_type: 'alliance' as const,
          standing: -10.0,
          label_ids: [],
        },
      ];

      jest
        .spyOn(client.contacts, 'getCharacterContacts')
        .mockResolvedValue(expectedContacts);
    });

    when('the client calls getCharacterContacts for the character', async () => {
      result = await client.contacts.getCharacterContacts(characterId);
    });

    then('the client shall return a list of contacts with their standings', () => {
      expect(result).toBeInstanceOf(Array);
      expect(result).toHaveLength(3);
      expect(result[0]).toHaveProperty('contact_id', 123456789);
      expect(result[0]).toHaveProperty('contact_type', 'character');
      expect(result[0]).toHaveProperty('standing', 10.0);
      expect(result[0]).toHaveProperty('label_ids');
      expect(result[2].standing).toBe(-10.0);
    });
  });

  test('WHILE a character has no contacts the client shall return an empty array', ({ given, when, then }) => {
    const characterId = 1689391488;
    let result: any;

    given('a valid character ID and the character has no contacts', () => {
      const emptyContacts: any[] = [];

      jest
        .spyOn(client.contacts, 'getCharacterContacts')
        .mockResolvedValue(emptyContacts);
    });

    when('the client calls getCharacterContacts for the character with no contacts', async () => {
      result = await client.contacts.getCharacterContacts(characterId);
    });

    then('the client shall return an empty array', () => {
      expect(result).toBeInstanceOf(Array);
      expect(result).toHaveLength(0);
    });
  });

  test('IF the access token is invalid or expired THEN the client shall throw a 403 forbidden error', ({ given, when, then }) => {
    const characterId = 1689391488;
    let error: any;

    given('an ESI client configured with an invalid or expired access token', () => {
      const forbiddenError = TestDataFactory.createError(403);

      jest
        .spyOn(client.contacts, 'getCharacterContacts')
        .mockRejectedValue(forbiddenError);
    });

    when('the client calls getCharacterContacts without valid authorization', async () => {
      try {
        await client.contacts.getCharacterContacts(characterId);
      } catch (e) {
        error = e;
      }
    });

    then('the client shall throw a 403 forbidden error', () => {
      expect(error).toBeInstanceOf(EsiError);
    });
  });

  test('WHEN getCharacterContactLabels is called the client shall return the label definitions', ({ given, when, then }) => {
    const characterId = 1689391488;
    let result: any;

    given('a valid character ID and the character has custom contact labels', () => {
      const expectedLabels = [
        { label_id: 1, label_name: 'Friendly' },
        { label_id: 2, label_name: 'Hostile' },
        { label_id: 3, label_name: 'Neutral' },
      ];

      jest
        .spyOn(client.contacts, 'getCharacterContactLabels')
        .mockResolvedValue(expectedLabels);
    });

    when('the client calls getCharacterContactLabels for the character', async () => {
      result = await client.contacts.getCharacterContactLabels(characterId);
    });

    then('the client shall return the contact label definitions', () => {
      expect(result).toBeInstanceOf(Array);
      expect(result).toHaveLength(3);
      expect(result[0]).toHaveProperty('label_id', 1);
      expect(result[0]).toHaveProperty('label_name', 'Friendly');
      expect(result[1]).toHaveProperty('label_name', 'Hostile');
    });
  });

  test('WHEN postCharacterContacts is called the client shall return the IDs of the added contacts', ({
    given,
    when,
    then,
  }) => {
    const characterId = 1689391488;
    let result: any;
    let newContacts: any;

    given('valid contact data with standings and label assignments', () => {
      newContacts = {
        contact_ids: [111111111, 222222222],
        standing: 5.0,
        label_ids: [1],
      };
      const expectedIds = [111111111, 222222222];

      jest
        .spyOn(client.contacts, 'postCharacterContacts')
        .mockResolvedValue(expectedIds);
    });

    when('the client calls postCharacterContacts with the contact data', async () => {
      result = await client.contacts.postCharacterContacts(
        characterId,
        newContacts,
      );
    });

    then('the client shall return the IDs of the added contacts', () => {
      expect(result).toBeInstanceOf(Array);
      expect(result).toHaveLength(2);
      expect(result).toContain(111111111);
      expect(result).toContain(222222222);
    });
  });

  test('WHEN deleteCharacterContacts is called the client shall complete the deletion successfully', ({
    given,
    when,
    then,
  }) => {
    const characterId = 1689391488;
    const contactIds = [111111111, 222222222];

    given('a valid character ID and existing contact IDs to remove', () => {
      jest
        .spyOn(client.contacts, 'deleteCharacterContacts')
        .mockResolvedValue(undefined);
    });

    when('the client calls deleteCharacterContacts with the contact IDs', async () => {
      await client.contacts.deleteCharacterContacts(characterId, contactIds);
    });

    then('the client shall complete the contact deletion successfully', () => {
      expect(client.contacts.deleteCharacterContacts).toHaveBeenCalledWith(
        characterId,
        contactIds,
      );
    });
  });

  test('WHEN getCorporationContacts is called the client shall return the corporation contact list', ({ given, when, then }) => {
    const corporationId = 1344654522;
    let result: any;

    given('a valid corporation ID and an authenticated ESI client', () => {
      const expectedContacts = [
        {
          contact_id: 99005338,
          contact_type: 'alliance' as const,
          standing: 10.0,
          label_ids: [],
        },
        {
          contact_id: 555555555,
          contact_type: 'character' as const,
          standing: -5.0,
          label_ids: [1],
        },
      ];

      jest
        .spyOn(client.contacts, 'getCorporationContacts')
        .mockResolvedValue(expectedContacts);
    });

    when('the client calls getCorporationContacts for the corporation', async () => {
      result = await client.contacts.getCorporationContacts(corporationId);
    });

    then('the client shall return the corporation contact list', () => {
      expect(result).toBeInstanceOf(Array);
      expect(result).toHaveLength(2);
      expect(result[0]).toHaveProperty('contact_id', 99005338);
      expect(result[0]).toHaveProperty('contact_type', 'alliance');
      expect(result[1]).toHaveProperty('standing', -5.0);
    });
  });

  test('WHEN getCorporationContactLabels is called the client shall return the corporation label definitions', ({ given, when, then }) => {
    const corporationId = 1344654522;
    let result: any;

    given('a valid corporation ID and the corporation has custom contact labels', () => {
      const expectedLabels = [
        { label_id: 1, label_name: 'War Target' },
        { label_id: 2, label_name: 'Ally' },
      ];

      jest
        .spyOn(client.contacts, 'getCorporationContactLabels')
        .mockResolvedValue(expectedLabels);
    });

    when('the client calls getCorporationContactLabels for the corporation', async () => {
      result = await client.contacts.getCorporationContactLabels(corporationId);
    });

    then('the client shall return the corporation contact label definitions', () => {
      expect(result).toBeInstanceOf(Array);
      expect(result).toHaveLength(2);
      expect(result[0]).toHaveProperty('label_name', 'War Target');
    });
  });

  test('WHEN a full contact management workflow is performed the client shall complete all operations successfully', ({
    given,
    when,
    then,
  }) => {
    const characterId = 1689391488;
    let finalContacts: any;

    given('a valid character ID and an ESI client configured for contact management', () => {
      const initialContacts = [
        {
          contact_id: 123456789,
          contact_type: 'character' as const,
          standing: 10.0,
          label_ids: [],
        },
      ];

      const labels = [{ label_id: 1, label_name: 'Friendly' }];

      const updatedContacts = [
        ...initialContacts,
        {
          contact_id: 333333333,
          contact_type: 'character' as const,
          standing: 5.0,
          label_ids: [1],
        },
      ];

      jest
        .spyOn(client.contacts, 'getCharacterContacts')
        .mockResolvedValueOnce(initialContacts)
        .mockResolvedValueOnce(updatedContacts);
      jest
        .spyOn(client.contacts, 'getCharacterContactLabels')
        .mockResolvedValue(labels);
      jest
        .spyOn(client.contacts, 'postCharacterContacts')
        .mockResolvedValue([333333333]);
    });

    when('the client lists contacts then adds new contacts and verifies the updated list', async () => {
      const newContactData = {
        contact_ids: [333333333],
        standing: 5.0,
        label_ids: [1],
      };

      const [contacts, contactLabels] = await Promise.all([
        client.contacts.getCharacterContacts(characterId),
        client.contacts.getCharacterContactLabels(characterId),
      ]);

      expect(contacts).toHaveLength(1);
      expect(contactLabels).toHaveLength(1);

      await client.contacts.postCharacterContacts(characterId, newContactData);

      finalContacts = await client.contacts.getCharacterContacts(characterId);
    });

    then('the client shall have completed all contact management operations successfully', () => {
      expect(finalContacts).toHaveLength(2);
      expect(finalContacts[1].contact_id).toBe(333333333);
      expect(finalContacts[1].standing).toBe(5.0);
    });
  });
});
